mapper.select:
SELECT t.id AS task_id, t.project_id, t.task_origin, t.current_stage, t.task_status, t.owner_user_id, t.manual_grade, t.version AS task_version, CASE t.current_stage WHEN 'P2' THEN a.id WHEN 'P3' THEN c.id WHEN 'P4' THEN p.id WHEN 'P5' THEN i.id WHEN 'P6' THEN x.id END AS stage_fact_id, CASE t.current_stage WHEN 'P2' THEN a.version WHEN 'P3' THEN c.version WHEN 'P4' THEN p.version WHEN 'P5' THEN i.version WHEN 'P6' THEN x.version END AS stage_fact_version, i.status_code AS current_approval_status FROM cut_task t LEFT JOIN cut_assessment a ON a.tenant_id = t.tenant_id AND a.id = t.current_assessment_id AND a.deleted = b'0' LEFT JOIN cut_cutover_checklist c ON c.tenant_id = t.tenant_id AND c.cutover_task_id = t.id AND c.current_marker = 1 AND c.deleted = b'0' LEFT JOIN cut_plan_revision p ON p.tenant_id = t.tenant_id AND p.cutover_task_id = t.id AND p.current_marker = 1 AND p.deleted = b'0' LEFT JOIN cut_approval_instance i ON i.tenant_id = t.tenant_id AND i.task_id = t.id AND i.replacement_approval_instance_id IS NULL AND i.deleted = b'0' LEFT JOIN cut_cutover_closure x ON x.tenant_id = t.tenant_id AND x.task_id = t.id AND x.deleted = b'0' WHERE t.tenant_id = #{query.tenantId} AND t.deleted = b'0' AND t.id > #{query.afterTaskId} AND t.project_id IN
#{projectId}
ORDER BY t.id ASC LIMIT #{query.limit}
